question.solution:
class Node:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def merge_two(a, b):
    tail = dummy = Node(0)
    while a is not None and b is not None:
        if a.val <= b.val:
            tail.next = a
            a = a.next
        else:
            tail.next = b
            b = b.next
        tail = tail.next
    tail.next = a if a is not None else b
    return dummy.next

def build(values):
    head = None
    for v in reversed(values):
        head = Node(v, head)
    return head

def values_of(head):
    out = []
    while head is not None:
        out.append(head.val)
        head = head.next
    return out

print(values_of(merge_two(build([1, 3, 5]), build([2, 4]))))
print(values_of(merge_two(None, build([2, 4]))))
print(values_of(merge_two(build([1, 1, 2]), build([1, 2, 2]))))

